// spec: specs/ssr-seo-public.md (1.2)
// seed: tests/seed.spec.ts
// Прод, только чтение: сырой HTML через request API.
import { test, expect } from '@playwright/test';
import { readSitemap, rawHtml, rootHtml, seoBody, h1s, links } from './ssr-seo.helpers';

test.describe('SSR и SEO публичных страниц — SSR-контент', () => {
  test('/search: в сыром HTML SSR-блок с h1 «עסקים למכירה» и ссылками на карточки объявлений #b3dc2e @desktop @prod-safe', async ({ request }) => {
    const sm = await readSitemap(request);
    expect(sm.listingIds.length, 'объявления в sitemap').toBeGreaterThan(0);

    const { status, html } = await rawHtml(request, '/search');
    expect(status).toBe(200);
    const seo = seoBody(rootHtml(html) ?? '');
    expect(seo, 'в #root есть [data-seo-body]').toBeTruthy();
    expect(seo!.attr).toBe('/search');
    expect(h1s(seo!.html)).toEqual(['עסקים למכירה']);

    const cards = links(seo!.html).filter((l) => l.href.includes('/businessdetail?id='));
    // На проде ~60 карточек (первая страница результатов); меньше — только если объявлений мало.
    expect(cards.length, 'ссылок на карточки').toBeGreaterThanOrEqual(Math.min(50, sm.listingIds.length));

    const known = new Set(sm.listingIds);
    const errors: string[] = [];
    for (const c of cards) {
      const id = new URL(c.href, 'https://www.biz4sale.co.il').searchParams.get('id') ?? '';
      if (!known.has(id)) errors.push(`${id}: нет в sitemap`);
      if (!c.text) errors.push(`${id}: пустое название`);
      // Строка карточки: «<название> – <категория · город · цена>» (части, что есть у объявления).
      if (c.rowText && c.rowText !== c.text && !c.rowText.startsWith(`${c.text} – `)) errors.push(`${id}: строка «${c.rowText}»`);
    }
    expect(errors, 'карточки SSR-блока').toEqual([]);
  });
});
